local _m = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local _l = {}
for _i = 1, #_m do _l[_m:sub(_i, _i)] = _i - 1 end
local function _d(_s)
    _s = _s:gsub("[^A-Za-z0-9+/]", "")
